const { spawn } = require("child_process")

const LOGO = "data:image/png;base64,"
const EXECUTE_ICON = "<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24' fill='none' stroke='var(--wox-theme-icon-color)' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M13 2 4.5 13.5h5.5L9 22l10-13h-6z'/></svg>"
const OPEN_ICON = "<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24' fill='none' stroke='var(--wox-theme-icon-color)' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M14 5h5v5M19 5l-9 9'/><path d='M13 7H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2v-7'/></svg>"
const COPY_ICON = "<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24' fill='none' stroke='var(--wox-theme-icon-color)' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><rect x='8' y='8' width='12' height='12' rx='2'/><path d='M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2'/></svg>"

const COMMAND_VALUE_LIMIT = 1000

const FALLBACK_LABELS = {
  command: "Command",
  link: "Link",
  run: "Run",
  copy: "Copy",
  empty: "No entries yet",
  emptyHint: "Add a command, a name, and a value in the plugin settings",
  missing: "That entry is no longer in the plugin settings",
  failed: "Could not run: %s"
}

function limitCommand(value) {
  const chars = Array.from(value)
  return chars.length > COMMAND_VALUE_LIMIT ? chars.slice(0, COMMAND_VALUE_LIMIT).join("") : value
}

function normalizeLink(value) {
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return value
  return "https://" + value
}

function launch(child, api, ctx, failedTemplate) {
  child.on("error", (error) => {
    const message = failedTemplate.replace("%s", error && error.message ? error.message : String(error))
    api.Notify(ctx, message).catch(() => {})
    api.Log(ctx, "Error", message).catch(() => {})
  })
  child.unref()
}

function openTarget(target, api, ctx, failedTemplate) {
  let child
  if (process.platform === "darwin") {
    child = spawn("open", [target], { detached: true, stdio: "ignore" })
  } else if (process.platform === "win32") {
    // Node re-quotes a single combined /c string, and cmd /s then strips those quotes.
    // start treats the leftover URL as a window title, plays the system beep, and exits without opening it.
    child = spawn("cmd.exe", ["/d", "/c", "start", '""', quoteWindows(target)], { detached: true, stdio: "ignore", windowsHide: true, windowsVerbatimArguments: true })
  } else {
    child = spawn("xdg-open", [target], { detached: true, stdio: "ignore" })
  }
  launch(child, api, ctx, failedTemplate)
}

function quoteWindows(value) {
  return '"' + value.replace(/"/g, '""') + '"'
}

function runCommand(command, api, ctx, failedTemplate) {
  let child
  if (process.platform === "win32") {
    child = spawn("cmd.exe", ["/d", "/s", "/c", command], { detached: true, stdio: "ignore", windowsHide: false })
  } else {
    child = spawn(process.env.SHELL || "/bin/zsh", ["-lc", command], { detached: true, stdio: "ignore" })
  }
  launch(child, api, ctx, failedTemplate)
}

function parseEntries(raw) {
  if (!raw) return []
  let rows
  try {
    rows = JSON.parse(raw)
  } catch {
    return []
  }
  if (!Array.isArray(rows)) return []
  const entries = []
  for (const row of rows) {
    if (!row || typeof row !== "object") continue
    const command = String(row.command || "").trim()
    const name = String(row.name || "").trim()
    let kind = String(row.kind || "command").trim()
    if (kind !== "link") kind = "command"
    let value = String(row.value || "").trim()
    if (kind === "command") value = limitCommand(value)
    if (!name || !value) continue
    entries.push({ command, name, kind, value })
  }
  return entries
}

// The host calls init and query as bare functions, so plugin state cannot live on this.
const pluginState = {
  api: null,
  entries: [],
  labels: { ...FALLBACK_LABELS }
}

async function reloadEntries(ctx) {
  const raw = await pluginState.api.GetSetting(ctx, "entries")
  pluginState.entries = parseEntries(raw)
}

async function loadLabels(ctx) {
  const keys = {
    command: "plugin_run_kind_command",
    link: "plugin_run_kind_link",
    run: "plugin_run_action_run",
    copy: "plugin_run_action_copy",
    empty: "plugin_run_empty",
    emptyHint: "plugin_run_empty_hint",
    missing: "plugin_run_missing",
    failed: "plugin_run_failed"
  }
  const next = { ...pluginState.labels }
  for (const field of Object.keys(keys)) {
    const translated = await pluginState.api.GetTranslation(ctx, keys[field])
    if (translated && translated !== keys[field]) next[field] = translated
  }
  pluginState.labels = next
}

function icon() {
  return { ImageType: "base64", ImageData: LOGO }
}

function svgIcon(svg) {
  return { ImageType: "svg", ImageData: svg }
}

function restore(mruData) {
  const key = mruData && mruData.ContextData && mruData.ContextData.key
  if (!key) return null
  const entry = findEntry(key)
  if (!entry) return null
  return resultFor(entry, 100)
}

function entryTitle(entry) {
  return entry.command ? entry.name + " - " + entry.command : entry.name
}

function findEntry(key) {
  const folded = String(key || "").trim().toLowerCase()
  if (!folded) return null
  return pluginState.entries.find((entry) => entry.name === key || entry.command === key)
    || pluginState.entries.find((entry) => entry.name.toLowerCase() === folded || entry.command.toLowerCase() === folded)
    || null
}

function resultFor(entry, score) {
  const labels = pluginState.labels
  const contextData = { key: entry.name }
  const runIcon = entry.kind === "command" ? EXECUTE_ICON : OPEN_ICON
  return {
    Title: entryTitle(entry),
    SubTitle: entry.value,
    Icon: icon(),
    IdentityKey: entry.name,
    Score: score,
    ContextData: contextData,
    Tails: [{ Type: "text", Text: labels[entry.kind] || entry.kind }],
    Actions: [
      {
        Name: labels.run,
        IsDefault: true,
        Icon: svgIcon(runIcon),
        ContextData: contextData,
        Action: async (actionCtx) => {
          await execute(actionCtx, entry)
        }
      },
      {
        Name: labels.copy,
        Icon: svgIcon(COPY_ICON),
        PreventHideAfterAction: true,
        ContextData: contextData,
        Action: async (actionCtx) => {
          await pluginState.api.Copy(actionCtx, { Type: "text", Text: entry.value })
        }
      }
    ]
  }
}

async function execute(ctx, entry) {
  const failed = pluginState.labels.failed
  if (entry.kind === "link") {
    openTarget(normalizeLink(entry.value), pluginState.api, ctx, failed)
    return
  }
  runCommand(entry.value, pluginState.api, ctx, failed)
}

const plugin = {
  async init(ctx, params) {
    pluginState.api = params.API
    await reloadEntries(ctx)
    await loadLabels(ctx)
    await pluginState.api.OnSettingChanged(ctx, async (callbackCtx) => {
      await reloadEntries(callbackCtx)
      await loadLabels(callbackCtx)
    })
    await pluginState.api.OnMRURestore(ctx, async (_ctx, mruData) => restore(mruData))
    await pluginState.api.RegisterPluginTool(ctx, {
      Tool: {
        Name: "run_entry",
        Description: "Run a configured Run plugin entry by its command or name",
        InputSchema: {
          type: "object",
          properties: { key: { type: "string", description: "Entry command or name" } },
          required: ["key"]
        },
        OutputSchema: {
          type: "object",
          properties: {
            name: { type: "string" },
            kind: { type: "string" }
          },
          required: ["name", "kind"]
        },
        Annotations: { ReadOnly: false, Destructive: false, Idempotent: false, RequiresUI: true }
      },
      Handler: async (toolCtx, option) => {
        const key = String(option && option.Arguments && option.Arguments.key || "").trim()
        await reloadEntries(toolCtx)
        const entry = findEntry(key)
        if (!entry) return { Error: { Code: "NOT_FOUND", Message: pluginState.labels.missing } }
        await execute(toolCtx, entry)
        return { Output: { name: entry.name, kind: entry.kind } }
      }
    })
  },

  async query(ctx, query) {
    await reloadEntries(ctx)
    await loadLabels(ctx)
    const search = String(query.Search || "").trim().toLowerCase()
    if (pluginState.entries.length === 0 && !search) {
      return {
        Results: [{
          Title: pluginState.labels.empty,
          SubTitle: pluginState.labels.emptyHint,
          Icon: icon(),
          Actions: []
        }]
      }
    }
    const matched = pluginState.entries.filter((entry) => {
      if (!search) return true
      const command = entry.command.toLowerCase()
      const name = entry.name.toLowerCase()
      return command === search || command.includes(search) || name.includes(search)
    })
    return {
      Results: matched.map((entry, index) => {
        const command = entry.command.toLowerCase()
        const name = entry.name.toLowerCase()
        let score = 1000 - index
        if (search && command === search) score = 3000 - index
        else if (search && command.startsWith(search)) score = 2000 - index
        else if (search && name === search) score = 1500 - index
        return resultFor(entry, Math.max(1, score))
      })
    }
  }
}

module.exports.plugin = plugin